from __future__ import annotations


def patch_production_login_ui(wrapper_source: str) -> str:
    """Restore the HealthyMe landing-page presentation on production /Login only."""

    marker = '    source_text = source_text.replace(\n        \'st.title("HealthyMe native full-member router")\',\n        \'st.title("HealthyMe native full application router")\',\n    )\n'
    replacement = '    login_start_marker = "def _login_page() -> None:\\n"\n    login_end_marker = "\\n\\ndef _admin_page() -> None:\\n"\n    login_start = source_text.find(login_start_marker)\n    login_end = source_text.find(login_end_marker, login_start)\n    if login_start < 0 or login_end < 0:\n        raise RuntimeError("H13R2 production login UI source markers are missing.")\n\n    production_login_source = \'def _login_page() -> None:\\n    context = _gate4_context()\\n    provider = str(context.get("provider") or "supabaseoidc")\\n    route_counts = {\\n        "read": sum(1 for item in _ROUTE_SPECS if item.checkpoint == "A-read"),\\n        "write": sum(1 for item in _ROUTE_SPECS if item.checkpoint == "B-write"),\\n        "remaining": sum(\\n            1 for item in _ROUTE_SPECS if item.checkpoint == "C-remaining"\\n        ),\\n    }\\n    diagnostics = {\\n        "build": BUILD,\\n        "rollback_build": ROLLBACK_BUILD,\\n        "native_identity_present": False,\\n        "full_member_route_count": len(_ROUTE_SPECS) + 2,\\n        "full_admin_route_count": len(_ADMIN_ROUTE_SPECS) + 1,\\n        "route_groups": route_counts,\\n        "real_admin_dashboard_loaded": False,\\n        "application_session_state_auth_source": False,\\n        "legacy_page_guard_used": False,\\n        "legacy_member_auth_retired": True,\\n        "native_member_guard_installed": True,\\n        "legacy_admin_auth_active": False,\\n        "native_admin_guard_installed": True,\\n        "auth0_restore_used": False,\\n        "nutritionist_role_promoted_to_admin": False,\\n        "custom_browser_marker_used": False,\\n        "durable_auth_session_used": False,\\n        "native_logout_installed": True,\\n        "local_storage_used": False,\\n        **_safe_cookie_snapshot(),\\n    }\\n\\n    st.markdown(\\n        """\\n        <style>\\n        .hm-production-login{max-width:1120px;margin:0 auto;}\\n        .hm-login-brand-row{display:flex;justify-content:space-between;align-items:center;margin:.15rem 0 2.1rem;}\\n        .hm-login-brand-name{font-size:2rem;font-weight:850;color:#004D40;line-height:1;}\\n        .hm-login-brand-sub{margin-top:.45rem;color:#5F6B66;font-size:.92rem;}\\n        .hm-login-secure-pill{padding:.52rem .9rem;border:1px solid #E5C76B;border-radius:999px;background:#FFF2CB;color:#8A5A00;font-weight:750;font-size:.78rem;}\\n        .hm-login-info{margin-top:1rem;padding:.72rem .82rem;border:1px solid #C9E0E7;border-radius:12px;background:#EAF5F8;color:#174B59;font-size:.84rem;line-height:1.35;}\\n        .hm-journey-card{border-radius:22px;padding:1.5rem 1.55rem;background:#087664;color:white;box-shadow:0 14px 28px rgba(7,76,64,.12);}\\n        .hm-journey-card h3{margin:0 0 .75rem;font-size:1.25rem;}\\n        .hm-journey-card p{margin:0 0 1.1rem;line-height:1.45;}\\n        .hm-journey-grid{display:grid;grid-template-columns:1fr 1fr;gap:.7rem;}\\n        .hm-journey-item{padding:.85rem .8rem;border-radius:14px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.22);font-weight:750;}\\n        .hm-feature-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:.8rem;margin-top:1.3rem;}\\n        .hm-feature{border:1px solid #DDD4C6;border-radius:15px;background:#FFFCF7;padding:.9rem 1rem;}\\n        .hm-feature b{display:block;color:#005B4B;margin-bottom:.2rem;}\\n        .hm-feature span{color:#454F4B;font-size:.88rem;}\\n        div[data-testid="stButton"] button[kind="primary"]{background:#006B57;border-color:#006B57;}\\n        @media(max-width:760px){\\n          .hm-login-brand-row{align-items:flex-start;gap:1rem;margin-bottom:1.2rem;}\\n          .hm-journey-grid,.hm-feature-strip{grid-template-columns:1fr;}\\n        }\\n        </style>\\n        <div class="hm-production-login">\\n          <div class="hm-login-brand-row">\\n            <div>\\n              <div class="hm-login-brand-name">HealthyMe</div>\\n              <div class="hm-login-brand-sub">Guided wellness assessment platform</div>\\n            </div>\\n            <div class="hm-login-secure-pill">Supabase secure access</div>\\n          </div>\\n        </div>\\n        """,\\n        unsafe_allow_html=True,\\n    )\\n\\n    login_col, journey_col = st.columns([0.96, 1.04], gap="large")\\n    with login_col:\\n        with st.container(border=True):\\n            st.markdown("## Secure Login")\\n            st.caption(\\n                "Sign in through Supabase Auth. HealthyMe grants access only to "\\n                "authorised Admin or Member accounts."\\n            )\\n            if st.button(\\n                "Continue with Supabase OIDC",\\n                key="h13r2_production_continue_oidc",\\n                type="primary",\\n                use_container_width=True,\\n            ):\\n                st.login(provider)\\n                st.stop()\\n            st.markdown(\\n                """\\n                <div class="hm-login-info">\\n                  <b>No public sign-up:</b><br>\\n                  Supabase confirms your identity. HealthyMe then checks your active\\n                  Admin or Member authorisation.\\n                </div>\\n                """,\\n                unsafe_allow_html=True,\\n            )\\n\\n    with journey_col:\\n        st.markdown(\\n            """\\n            <div class="hm-journey-card">\\n              <h3>Your wellness journey</h3>\\n              <p>A premium, expert-led flow from assessment to actionable wellness guidance.</p>\\n              <div class="hm-journey-grid">\\n                <div class="hm-journey-item">✓ Supabase Secure Login</div>\\n                <div class="hm-journey-item">✓ Lifestyle Assessment</div>\\n                <div class="hm-journey-item">✓ NSP Assessment</div>\\n                <div class="hm-journey-item">🔒 Expert Review</div>\\n              </div>\\n            </div>\\n            """,\\n            unsafe_allow_html=True,\\n        )\\n\\n    st.markdown(\\n        """\\n        <div class="hm-feature-strip">\\n          <div class="hm-feature"><b>Secure</b><span>Supabase OIDC</span></div>\\n          <div class="hm-feature"><b>Role-based</b><span>Admin / Member</span></div>\\n          <div class="hm-feature"><b>Private</b><span>Native Streamlit session</span></div>\\n        </div>\\n        """,\\n        unsafe_allow_html=True,\\n    )\\n\\n    with st.expander("Technical diagnostics", expanded=False):\\n        st.code(BUILD)\\n        st.metric("Native Streamlit identity", "Absent")\\n        st.code(\\n            json.dumps(diagnostics, indent=2, sort_keys=True),\\n            language="json",\\n        )\\n\'\n    source_text = (\n        source_text[:login_start]\n        + production_login_source\n        + source_text[login_end:]\n    )\n'

    if marker not in wrapper_source:
        raise RuntimeError("H13R2 production login UI insertion marker missing.")
    return wrapper_source.replace(marker, replacement, 1)
